3	import (
4		"os"
5		"path/filepath"
6		"strings"
7		"testing"
8	)
9	
10	const validRecord = `{
11	  "schemaVersion": 1,
12	  "generator": {"tool": "Intropy.Topology.Generation", "version": "0.1.0", "source": "integrations@3f9c2e1"},
13	  "system": {"name": "product-distribution", "owner": "group:default/team-integration", "domain": "distribution"},
14	  "components": [
15	    {"name": "pim-extractor", "type": "extractor", "tags": ["int-042"], "project": "pim-extractor",
16	     "workload": "cronjob", "trigger": {"kind": "schedule", "schedule": "*/15 * * * *"}},
17	    {"name": "erp-loader", "type": "loader", "tags": ["int-042"], "project": "erp-loader"},
18	    {"name": "mock-pim", "type": "mock", "lifecycle": "local", "implements": "system:default/pim",
19	     "profiles": ["local"], "image": "ghcr.io/integrio/mock-pim:1.2.0"}
20	  ],
21	  "resources": [
22	    {"name": "product-raw", "type": "topic", "pubsub": "product-distribution-pubsub", "entity": "RawProduct"},
23	    {"name": "pim", "type": "connector", "transport": "sftp", "daprComponent": "pim",
24	     "externalSystem": "system:default/pim"}
25	  ],
26	  "apis": [
27	    {"name": "product-enriched", "type": "asyncapi", "direction": "provides",
28	     "contract": "Integrio.Contracts.Products", "topic": "resource:product-enriched"}
29	  ],
30	  "edges": [
31	    {"from": "resource:pim", "to": "component:pim-extractor", "kind": "connector"},
32	    {"from": "component:pim-extractor", "to": "resource:product-raw", "kind": "publish", "port": "default"},
33	    {"from": "resource:product-raw", "to": "component:erp-loader", "kind": "consume"}
34	  ]
35	}`
36	
37	func writeRecord(t *testing.T, systemDir, body string) string {
38		t.Helper()
39		dir := filepath.Join(systemDir, ".intropy")
40		if err := os.MkdirAll(dir, 0o755); err != nil {
41			t.Fatal(err)
42		}
43		path := filepath.Join(dir, "topology.json")
44		if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
45			t.Fatal(err)
46		}
47		return path
48	}
49	
50	func TestLoadValid(t *testing.T) {
51		path := writeRecord(t, t.TempDir(), validRecord)
52		got, err := Load(path)
53		if err != nil {
54			t.Fatalf("Load: %v", err)
55		}
56		if got.System.Name != "product-distribution" || got.System.Owner != "group:default/team-integration" {
57			t.Errorf("system = %+v", got.System)
58		}
59		if got.Generator.Source != "integrations@3f9c2e1" {
60			t.Errorf("generator = %+v", got.Generator)
61		}
62		if len(got.Components) != 3 || len(got.Resources) != 2 || len(got.APIs) != 1 || len(got.Edges) != 3 {
63			t.Fatalf("entity counts = %d/%d/%d/%d, want 3/2/1/3",
64				len(got.Components), len(got.Resources), len(got.APIs), len(got.Edges))
65		}
66		if c := got.Components[0]; c.Trigger == nil || c.Trigger.Kind != "schedule" || c.Trigger.Schedule != "*/15 * * * *" {
67			t.Errorf("extractor trigger = %+v", c.Trigger)
68		}
69		if r := got.Resources[1]; r.Type != "connector" || r.DaprComponent != "pim" || r.ExternalSystem != "system:default/pim" {
70			t.Errorf("connector = %+v", r)
71		}
72		if e := got.Edges[1]; e.Kind != "publish" || e.Port != "default" {
73			t.Errorf("publish edge = %+v", e)
74		}
75	}
76	
77	func TestLoadMissing(t *testing.T) {
78		_, err := Load(filepath.Join(t.TempDir(), "nope.json"))
79		if err == nil {
80			t.Fatal("expected error for missing file")
81		}
82	}
83	
84	func TestLoadMalformed(t *testing.T) {
85		path := writeRecord(t, t.TempDir(), "{not json")
86		if _, err := Load(path); err == nil || !strings.Contains(err.Error(), "parse topology record") {
87			t.Fatalf("err = %v, want parse error", err)
88		}
89	}
90	
91	// An unknown schema version is surfaced as an error, not guessed at.
92	func TestLoadUnsupportedVersion(t *testing.T) {
93		path := writeRecord(t, t.TempDir(), `{"schemaVersion": 99, "system": {"name": "x"}}`)
94		if _, err := Load(path); err == nil || !strings.Contains(err.Error(), "unsupported schema version 99") {
95			t.Fatalf("err = %v, want unsupported version error", err)
96		}
97	}
98	
99	func TestListFindsSystems(t *testing.T) {
100		root := t.TempDir()
101		writeRecord(t, filepath.Join(root, "distribution", "product-distribution"), validRecord)
102		other := strings.Replace(validRecord, "product-distribution", "order-intake", 1)
103		writeRecord(t, filepath.Join(root, "sales", "order-intake"), other)
104		// A dir without a record is walked through, not reported.
105		if err := os.MkdirAll(filepath.Join(root, "empty"), 0o755); err != nil {
106			t.Fatal(err)
107		}
108	
109		entries, warnings := List(root)
110		if len(warnings) != 0 {
111			t.Fatalf("warnings = %v", warnings)
112		}
113		if len(entries) != 2 {
114			t.Fatalf("entries = %d, want 2", len(entries))
115		}
116		// Lexical walk order: distribution before sales.
117		if entries[0].System.Name != "product-distribution" || entries[1].System.Name != "order-intake" {
118			t.Errorf("systems = %q, %q", entries[0].System.Name, entries[1].System.Name)
119		}
120		if want := filepath.Join(root, "distribution", "product-distribution"); entries[0].Path != want {
121			t.Errorf("path = %q, want %q", entries[0].Path, want)
122		}
123	}
124	
125	// A malformed record is a warning, and its directory is still treated as a
126	// system root (not descended into), so one bad system cannot hide the rest.
127	func TestListMalformedIsWarning(t *testing.T) {
128		root := t.TempDir()
129		writeRecord(t, filepath.Join(root, "bad"), "{broken")
130		writeRecord(t, filepath.Join(root, "good"), validRecord)
131	
132		entries, warnings := List(root)
133		if len(entries) != 1 || entries[0].System.Name != "product-distribution" {
134			t.Fatalf("entries = %+v, want just the good system", entries)
135		}
136		if len(warnings) != 1 {
137			t.Fatalf("warnings = %v, want 1", warnings)
138		}
139	}
140	
141	func TestListSkipsUninterestingDirs(t *testing.T) {
142		root := t.TempDir()
143		writeRecord(t, filepath.Join(root, "node_modules", "pkg"), validRecord)
144		writeRecord(t, filepath.Join(root, ".git", "sys"), validRecord)
145	
146		entries, warnings := List(root)
147		if len(entries) != 0 || len(warnings) != 0 {
148			t.Fatalf("entries = %v, warnings = %v, want none", entries, warnings)
149		}
150	}
