func TestListFindsSystems(t *testing.T) {
	root := t.TempDir()
	writeRecord(t, filepath.Join(root, "distribution", "price-distribution"), validRecord)
	other := strings.Replace(validRecord, `"system": "distribution"`, `"system": "order-intake"`, 1)
	writeRecord(t, filepath.Join(root, "sales", "order-intake"), other)
	// A dir without a record is walked through, not reported.
	if err := os.MkdirAll(filepath.Join(root, "empty"), 0o755); err != nil {
		t.Fatal(err)
	}

	entries, warnings := List(root)
	if len(warnings) != 0 {
		t.Fatalf("warnings = %v", warnings)
	}
	if len(entries) != 2 {
		t.Fatalf("entries = %d, want 2", len(entries))
	}
	// Lexical walk order: distribution before sales.
	if entries[0].System != "distribution" || entries[1].System != "order-intake" {
		t.Errorf("systems = %q, %q", entries[0].System, entries[1].System)
	}
	if want := filepath.Join(root, "distribution", "price-distribution"); entries[0].Path != want {
		t.Errorf("path = %q, want %q", entries[0].Path, want)
	}
}

// A malformed record is a warning, and its directory is still treated as a
// system root (not descended into), so one bad system cannot hide the rest.
func TestListMalformedIsWarning(t *testing.T) {
	root := t.TempDir()
	writeRecord(t, filepath.Join(root, "bad"), "{broken")
	writeRecord(t, filepath.Join(root, "good"), validRecord)

	entries, warnings := List(root)
	if len(entries) != 1 || entries[0].System != "distribution" {
		t.Fatalf("entries = %+v, want just the good system", entries)
	}
	if len(warnings) != 1 {
		t.Fatalf("warnings = %v, want 1", warnings)
	}
}

func TestListSkipsUninterestingDirs(t *testing.T) {
	root := t.TempDir()
	writeRecord(t, filepath.Join(root, "node_modules", "pkg"), validRecord)
	writeRecord(t, filepath.Join(root, ".git", "sys"), validRecord)

	entries, warnings := List(root)
	if len(entries) != 0 || len(warnings) != 0 {
		t.Fatalf("entries = %v, warnings = %v, want none", entries, warnings)
	}
}

