// Declared system topology (internal/topology). A system's AppHost project
// generates .intropy/topology.json; entities follow the Backstage catalog
// taxonomy (Components, Resources, APIs) while `edges` is an Intropy
// extension carrying flow direction, which Backstage relations cannot
// express. Systems without a record simply do not appear here — the flow
// canvas falls back to its heuristics for them.

export interface TopologyTrigger {
  kind: string
  /** Cron expression, present when kind is "schedule". */
  schedule?: string
}

export interface TopologyComponent {
  name: string
  /** Block type (extractor, assembler, loader, …) or "mock". */
  type: string
  /** Integration identifiers, e.g. "int-042" — the Backstage catalog tags. */
  tags?: string[]
  /** Directory relative to the system root; joins the node to its
   *  scaffolded integration project. */
  project?: string
  workload?: string
  /** Declared only when not derivable from edges (a consume edge already
   *  implies a topic trigger; a schedule does not). */
  trigger?: TopologyTrigger
  image?: string
  lifecycle?: string
  /** Mocks: catalog ref of the external system this component stands in for. */
  implements?: string
  profiles?: string[]
}

export interface TopologyResource {
  name: string
  /** "topic" | "pubsub" | "connector" | … — decides which fields apply. */
  type: string
  pubsub?: string
  /** Data entity carried on a topic, e.g. "RawProduct". */
  entity?: string
  transport?: string
  /** The Dapr component's metadata.name, joinable against component YAML. */
  daprComponent?: string
  /** Catalog ref of the external system behind a connector, e.g. "system:default/pim". */
  externalSystem?: string
}

export interface TopologyApi {
  name: string
  type: string
  /** "provides" when this system exports the contract, "consumes" when it
   *  imports one another system provides. */
  direction: 'provides' | 'consumes'
  contract?: string
  /** Ref to the topic resource carrying the contract, e.g. "resource:price-raw". */
  topic?: string
}

export interface TopologyEdge {
  /** Entity refs: "<kind>:<name>" for entities in this file,
   *  "<kind>:<namespace>/<name>" for catalog entities outside it. */
  from: string
  to: string
  kind: 'publish' | 'consume' | 'connector' | 'uses'
  /** Component output port a publish edge leaves through. */
  port?: string
}

export interface Topology {
  /** Root-relative system directory, same identifier space as Integration.path. */
  path: string
  schemaVersion: number
  generator: { tool: string; version?: string; source?: string }
  system: { name: string; owner?: string; domain?: string }
  components?: TopologyComponent[]
  resources?: TopologyResource[]
  apis?: TopologyApi[]
  edges?: TopologyEdge[]
}

