// Declared system topology (internal/topology). A system's AppHost project
// generates .intropy/topology.json (apiVersion topology.intropy.io/v1). Wiring
// is inlined on each component — the topics it subscribes to and publishes on
// and the connectors it uses — while the top-level `topics` and `connectors`
// sections are the lookup tables those inline references resolve against.
// Systems without a record simply do not appear here — the flow canvas falls
// back to its heuristics for them.

/** A component's subscription to a pub/sub topic. */
export interface TopicRef {
  pubsub: string
  topic: string
}

/** A component's output onto a pub/sub topic. */
export interface Publication {
  /** Component output port the message leaves through. */
  port?: string
  pubsub: string
  topic: string
}

/** A component's use of an external connector. */
export interface ConnectorUse {
  connector: string
  /** "in" (external → component) or "out" (component → external). */
  direction: 'in' | 'out'
}

export interface TopologyComponent {
  name: string
  /** Block type: extractor, loader, transactionalIntegration, … */
  kind: string
  subscribes?: TopicRef[]
  publishes?: Publication[]
  connectors?: ConnectorUse[]
  /** Contract surfaces — parsed but not yet rendered (shape not finalized). */
  provides?: unknown[]
  consumes?: unknown[]
}

/** A declared pub/sub topic: metadata for a (pubsub, topic) pair components
 *  reference. */
export interface TopologyTopic {
  pubsub: string
  topic: string
  contract?: string
  publishers?: string[]
  subscribers?: string[]
}

export interface TopologyTransport {
  type: string
  supportsInput: boolean
  supportsOutput: boolean
}

/** An external system integration point. */
export interface TopologyConnector {
  name: string
  externalSystem?: string
  transport: TopologyTransport
  directions?: Array<'in' | 'out'>
  usedBy?: string[]
}

export interface Topology {
  /** Root-relative system directory, same identifier space as Integration.path. */
  path: string
  apiVersion: string
  kind?: string
  /** System name (a bare string in v1). */
  system: string
  components?: TopologyComponent[]
  topics?: TopologyTopic[]
  connectors?: TopologyConnector[]
  /** Contract surfaces — parsed but not yet rendered (shape not finalized). */
  apis?: unknown[]
}

import {
  api,
  type DaprComponent,
  type IntegrationDetail,
  type Topology,
} from '../api'

